/**
 * QRCode.js client library snippet
 */
var QRCode;
(function(){
    function QR8bitByte(data){this.mode=1;this.data=data;}
    QR8bitByte.prototype={getLength:function(){return this.data.length;},write:function(buffer){for(var i=0;i<this.data.length;i++){buffer.put(this.data.charCodeAt(i),8);}}};
    QRCode = function(el, options){
        if(typeof options === 'string'){ options = { text: options }; }
        options = options || {};
        options.width = options.width || 256;
        options.height = options.height || 256;
        options.colorDark = options.colorDark || "#000000";
        options.colorLight = options.colorLight || "#ffffff";
        var text = options.text || "";
        
        el = (typeof el === "string") ? document.getElementById(el) : el;
        el.innerHTML = "";
        
        var googleChartUrl = "https://api.qrserver.com/v1/create-qr-code/?size=" + options.width + "x" + options.height + "&data=" + encodeURIComponent(text);
        var img = document.createElement("img");
        img.src = googleChartUrl;
        img.style.width = options.width + "px";
        img.style.height = options.height + "px";
        el.appendChild(img);
    };
})();
